            boolean ကိုက်ညီ = true; for (int အတွင်းနေရာ = 0; အတွင်းနေရာ < အချက်အရေအတွက်; အတွင်းနေရာ++) if (ကိန်းရှင်အမည်[ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း * 32 + အတွင်းနေရာ] != ဒေတာအခင်းအကျင်း[နေရာစတင် + အတွင်းနေရာ]) ကိုက်ညီ = false;
            if (ကိုက်ညီ) { for (int အတွင်းနေရာ = 0; အတွင်းနေရာ < တန်ဖိုးအလျား[ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း]; အတွင်းနေရာ++) တန်ဖိုးထား(ကိန်းရှင်ဒေတာ[ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း * 256 + အတွင်းနေရာ]); return; }
