            int အက္ခရာကုဒ် = မူရင်းကုဒ်[အခြေနေရာ + စာညွှန်းဖတ်++];
            if (အက္ခရာကုဒ် == ကိုးကားအမှတ်) { ကိုးကားအမှတ် = 0; continue; }
